// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {ILocalAdapter} from "../interfaces/ILocalAdapter.sol";
import {IInboxCallback} from "../interfaces/IInboxCallback.sol";
import {InboxTokenTransfer} from "../libraries/InboxTokenTransfer.sol";

/// @title LocalAdapter
/// @author Agustin Aguilar
/// @notice Base contract for local operation adapters that execute through a PDA inbox
abstract contract LocalAdapter is ILocalAdapter {
  error InsufficientInboxBalance(address _token, uint256 _balance, uint256 _amount);
  error InboxTokenTransferFailed(address _token);

  function _executeInboxTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bytes memory _result)
  {
    return _executeInboxTransactionFromRoute(msg.sender, _inbox, _target, _value, _data);
  }

  function _executeInboxTransactionFromRoute(
    address _route,
    address _inbox,
    address _target,
    uint256 _value,
    bytes memory _data
  ) internal returns (bytes memory _result) {
    return IInboxCallback(_route).executeLocalInboxTransaction(_inbox, _target, _value, _data);
  }

  function _payInboxAsset(address _inbox, address _recipient, address _token, uint256 _amount) internal {
    if (_token == address(0)) {
      _payInboxNative(_inbox, _recipient, _amount);
    } else {
      _payInboxToken(_inbox, _recipient, _token, _amount);
    }
  }

  function _payInboxNative(address _inbox, address _recipient, uint256 _amount) internal {
    uint256 balance = _inbox.balance;
    if (balance < _amount) {
      revert InsufficientInboxBalance(address(0), balance, _amount);
    }

    _executeInboxTransaction(_inbox, _recipient, _amount, "");
  }

  function _payInboxToken(address _inbox, address _recipient, address _token, uint256 _amount) internal {
    uint256 balance = _inboxAssetBalance(_inbox, _token);
    if (balance < _amount) {
      revert InsufficientInboxBalance(_token, balance, _amount);
    }

    _executeInboxTokenTransferFromRoute(msg.sender, _inbox, _token, _recipient, _amount, balance);
  }

  function _executeInboxTokenTransfer(address _inbox, address _token, address _recipient, uint256 _amount)
    internal
    returns (bytes memory _result)
  {
    return _executeInboxTokenTransferFromRoute(msg.sender, _inbox, _token, _recipient, _amount);
  }

  function _executeInboxTokenTransferFromRoute(
    address _route,
    address _inbox,
    address _token,
    address _recipient,
    uint256 _amount
  ) internal returns (bytes memory _result) {
    return _executeInboxTokenTransferFromRoute(
      _route, _inbox, _token, _recipient, _amount, IERC20(_token).balanceOf(_inbox)
    );
  }

  /// @param _balanceBefore Inbox balance of `_token` before the transfer, used to verify a `false` result
  function _executeInboxTokenTransferFromRoute(
    address _route,
    address _inbox,
    address _token,
    address _recipient,
    uint256 _amount,
    uint256 _balanceBefore
  ) internal returns (bytes memory _result) {
    bytes memory result = _executeInboxTransactionFromRoute(
      _route, _inbox, _token, 0, abi.encodeCall(IERC20.transfer, (_recipient, _amount))
    );
    if (!InboxTokenTransfer.succeeded(result, _token, _inbox, _balanceBefore, _amount)) {
      revert InboxTokenTransferFailed(_token);
    }

    return result;
  }

  function _inboxAssetBalance(address _inbox, address _token) internal view returns (uint256) {
    if (_token == address(0)) {
      return _inbox.balance;
    }

    return IERC20(_token).balanceOf(_inbox);
  }

  function _resolveAmountIn(uint256 _amountIn, uint256 _balance) internal pure returns (uint256) {
    return _amountIn == 0 ? _balance : _amountIn;
  }
}

