// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {LocalAdapter} from "./LocalAdapter.sol";
import {LocalQuote} from "../interfaces/ILocalAdapter.sol";
import {IWETH} from "../interfaces/IWETH.sol";

/// @title WethAdapter
/// @author Agustin Aguilar
/// @notice Local adapter for wrapping and unwrapping WETH from an inbox
contract WethAdapter is LocalAdapter {
  IWETH public immutable WETH;

  event WethRouteExecuted(
    address indexed _inbox, address indexed _tokenIn, address indexed _tokenOut, uint256 _amountIn, uint256 _amountOut
  );

  error ZeroAddress();
  error InvalidAmount();
  error UnsupportedRoute(address _tokenIn, address _tokenOut);

  constructor(address _weth) {
    if (_weth == address(0)) {
      revert ZeroAddress();
    }

    WETH = IWETH(_weth);
  }

  /// @notice Quotes a WETH wrap or unwrap for an explicit non-zero input amount.
  function quote(address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    view
    override
    returns (LocalQuote memory _quote)
  {
    address weth = address(WETH);
    if (!((_tokenIn == address(0) && _tokenOut == weth) || (_tokenIn == weth && _tokenOut == address(0)))) {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    if (_amountIn == 0) {
      revert InvalidAmount();
    }

    return LocalQuote({amountIn: _amountIn, amountOut: _amountIn});
  }

  /// @notice Executes a WETH wrap or unwrap. `_amountIn == 0` uses the full inbox balance.
  function execute(address _inbox, address _tokenIn, address _tokenOut, uint256 _amountIn, bytes calldata)
    external
    override
    returns (uint256 _amountOut)
  {
    address weth = address(WETH);

    if (_tokenIn == address(0) && _tokenOut == weth) {
      _amountOut = _wrap(_inbox, _amountIn);
    } else if (_tokenIn == weth && _tokenOut == address(0)) {
      _amountOut = _unwrap(_inbox, _amountIn);
    } else {
      revert UnsupportedRoute(_tokenIn, _tokenOut);
    }

    emit WethRouteExecuted(_inbox, _tokenIn, _tokenOut, _amountOut, _amountOut);
  }

  function _wrap(address _inbox, uint256 _amountIn) internal returns (uint256 _amountOut) {
    _amountOut = _resolveAmountIn(_amountIn, _inbox.balance);
    if (_amountOut == 0) {
      revert InvalidAmount();
    }

    _executeInboxTransaction(_inbox, address(WETH), _amountOut, abi.encodeCall(IWETH.deposit, ()));
  }

  function _unwrap(address _inbox, uint256 _amountIn) internal returns (uint256 _amountOut) {
    _amountOut = _resolveAmountIn(_amountIn, WETH.balanceOf(_inbox));
    if (_amountOut == 0) {
      revert InvalidAmount();
    }

    _executeInboxTransaction(_inbox, address(WETH), 0, abi.encodeCall(IWETH.withdraw, (_amountOut)));
  }
}

