// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @title InboxTokenTransfer
/// @notice Result check for ERC-20 `transfer` calls sent from a PDA inbox.
library InboxTokenTransfer {
  /// @notice Whether an inbox `transfer` of `_amount` succeeded
  /// @dev An empty result (no-return tokens) or `true` is success. A `false` result is only
  /// accepted if the inbox balance dropped by exactly `_amount`: Tron USDT
  /// (TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t) moves the funds but returns `false` from `transfer`.
  /// The balance is only read on that branch.
  /// @param _result Raw result of the `transfer` call
  /// @param _token Token that was transferred
  /// @param _inbox Inbox that sent the transfer
  /// @param _balanceBefore Inbox balance of `_token` before the transfer
  /// @param _amount Amount transferred
  function succeeded(bytes memory _result, address _token, address _inbox, uint256 _balanceBefore, uint256 _amount)
    internal
    view
    returns (bool)
  {
    if (_result.length == 0 || abi.decode(_result, (bool))) {
      return true;
    }

    return _balanceBefore >= _amount && IERC20(_token).balanceOf(_inbox) == _balanceBefore - _amount;
  }
}

